import re
s=open('xl/worksheets/sheet2.xml').read()
rows = re.findall(r'<row r=\"(\d+)\" spans=\"1:23\">(.*?)</row>', s)
for r, content in rows:
    if int(r)<=30:
        cs = re.findall(r'<c r=\"([A-Z]+\d+)\"[^>]*?(?:/>|>(.*?)</c>)', content)
        line=[]
        for coord, inner in cs:
            val = re.sub(r'<[^>]+>','',inner)
            if inner.startswith('<f'):
                line.append(f'{coord}=F[{val[:30]}]')
            elif val!='':
                line.append(f'{coord}={val}')
        print(r, ' '.join(line))
"

